/* v0.36: functional river biomass, normalized C/N/P; experimental. */
const Aquatic=(()=>{
const V=typeof module!=='undefined'?require('./vertebrates'):Vertebrates,E=typeof module!=='undefined'?require('./ecology'):Eco;
const names=['algae','plankton','larvae','shrimp','fish','detritus'],lim=(x,a=0,b=1)=>Math.max(a,Math.min(b,x)),pool=(c=0,n=c*.08,p=c*.012)=>({c,n,p});
function add(a,b){for(const k of ['c','n','p'])a[k]+=b[k]}
function take(a,c){const f=a.c>0?lim(c/a.c):0,b=pool(a.c*f,a.n*f,a.p*f);for(const k of ['c','n','p'])a[k]-=b[k];return b}
function create(seed=42){const s=V.create(seed);s.version=36;s.aqua=[];s.aquaEvents={fixed:0,feeding:0,fishMeals:0,landN:0,landP:0,landC:0,decomp:0,oxygenStress:0,harvestC:0};s.ledger.pOut=0;s.ledger.externalP=0;for(const c of s.cells){c.soilP=c.channel?0:.045;c.rockP=c.channel?0:.18}for(let y=0;y<E.H;y++){const ids=s.cells.map((c,i)=>c.channel&&c.y===y?i:-1).filter(i=>i>=0);s.aqua.push({y,ids,n:.05,p:.012,o:.9,water:ids.reduce((t,i)=>t+s.cells[i].surface,0),algae:pool(.09),plankton:pool(.022),larvae:pool(.035),shrimp:pool(.026),fish:pool(.045),detritus:pool(.11)})}s.last.pError=0;return s}
function totals(s){const t=V.totals(s);t.p=0;for(const c of s.cells)t.p+=c.soilP+c.rockP;for(const r of s.aqua){t.n+=r.n;t.p+=r.p;for(const k of names){t.c+=r[k].c;t.n+=r[k].n;t.p+=r[k].p}}return t}
function eat(s,r,prey,pred,rate){let q=take(r[prey],rate);if(q.c<=0)return;let a=pool(q.c*.37,q.n*.37,q.p*.37);add(r[pred],a);add(r.detritus,pool(q.c-a.c,q.n-a.n,q.p-a.p));s.aquaEvents.feeding+=q.c;if(pred==='fish')s.aquaEvents.fishMeals+=q.c}
function respire(s,r,k,rate){const q=take(r[k],rate);s.ledger.carbonOut+=q.c;r.n+=q.n;r.p+=q.p;return q.c}
function tick(s){const before=totals(s),prev={...s.ledger};V.tick(s);const hour=(s.step-1)%4,light=s.light==='dark'?0:[0,.72,1,.22][hour]*(1-s.cloud*.65),ev=s.aquaEvents;
for(const c of s.cells){if(c.channel)continue;const r=s.aqua[c.y],near=Math.abs(c.x-(19+Math.sin(c.y*.25)*3))<5;let w=Math.min(c.rockP,.000018*(.3+c.water/c.cap));c.rockP-=w;c.soilP+=w;let p=Math.min(c.soilP,c.soilP*Math.min(.015,(c.runoff||0)*.0015));c.soilP-=p;if(near){r.p+=p;ev.landP+=p;const n=(c.leachedN||0)*.65;r.n+=n;s.ledger.nOut-=n;ev.landN+=n;let l=Math.min(c.litter,c.litter*Math.min(.015,(c.runoff||0)*.0012)),ln=c.litter>0?c.ln*l/c.litter:0;c.litter-=l;c.ln-=ln;add(r.detritus,pool(l,ln,0));ev.landC+=l}else s.ledger.pOut+=p}
for(const r of s.aqua){r.water=r.ids.reduce((t,i)=>t+s.cells[i].surface,0);const wet=lim(r.water/3),temp=lim(1-Math.abs(s.temp-26)/18),air=.07+Math.min(.18,r.water*.003),crowd=lim(1-r.algae.c/.85),shade=1/(1+r.algae.c*2+r.detritus.c*.8);const g=Math.min(r.n/.08,r.p/.012,r.algae.c*.24*light*wet*temp*crowd*shade);r.n-=g*.08;r.p-=g*.012;add(r.algae,pool(g));s.ledger.carbonIn+=g;ev.fixed+=g;
for(const [prey,pred,rate] of [['algae','plankton',.08],['algae','larvae',.055],['detritus','shrimp',.055],['plankton','larvae',.025],['larvae','fish',.045],['shrimp','fish',.04]])eat(s,r,prey,pred,Math.min(r[prey].c*.07,r[pred].c*rate*wet*r.o*r[prey].c/(r[prey].c+.06)));
let d=0;for(const k of names.slice(0,-1)){let m=r[k].c*(.002+.045*(1-wet)+(k==='fish'?.065:.025)*lim((.45-r.o)/.45));add(r.detritus,take(r[k],m));d+=respire(s,r,k,r[k].c*(k==='algae'?.003:.004)*wet)}let decay=respire(s,r,'detritus',r.detritus.c*.045*wet*temp*(.1+.9*r.o));ev.decomp+=decay;d+=decay;r.o=lim(r.o+air*(wet*(.98-Math.max(0,s.temp-26)*.025)-r.o)+g*.8-d*4);if(r.o<.3&&r.water>0)ev.oxygenStress++}
for(let y=s.aqua.length-1;y>=0;y--){const r=s.aqua[y],next=s.aqua[y+1],f=lim(r.water*.0007,0,.025);for(const k of ['n','p']){let q=r[k]*f;r[k]-=q;if(next)next[k]+=q;else s.ledger[k+'Out']+=q}for(const k of ['plankton','detritus']){let q=take(r[k],r[k].c*f);if(next)add(next[k],q);else{s.ledger.carbonOut+=q.c;s.ledger.nOut+=q.n;s.ledger.pOut+=q.p}}}
const after=totals(s),L=s.ledger;s.last={waterError:s.last.waterError,cError:after.c-before.c-(L.carbonIn-prev.carbonIn)+(L.carbonOut-prev.carbonOut),nError:after.n-before.n+(L.nOut-prev.nOut),pError:after.p-before.p+(L.pOut-prev.pOut)};return s}
function metrics(s){let m={o:0,wet:0,n:0,p:0};for(const k of names)m[k]=0;for(const r of s.aqua){m.o+=r.o/s.aqua.length;m.wet+=r.water>3?1:0;m.n+=r.n;m.p+=r.p;for(const k of names)m[k]+=r[k].c}return m}
function edit(s,y,action){const r=s.aqua[y];if(!r)return false;if(action==='nutrients'){r.n+=.2;r.p+=.05;s.ledger.externalN=(s.ledger.externalN||0)+.2;s.ledger.externalP+=.05}else if(action==='organic'){add(r.detritus,pool(.8));s.ledger.externalC=(s.ledger.externalC||0)+.8;s.ledger.externalN=(s.ledger.externalN||0)+.064;s.ledger.externalP+=.0096}else if(action==='fish'){let q=take(r.fish,r.fish.c*.25);s.ledger.carbonOut+=q.c;s.ledger.nOut+=q.n;s.ledger.pOut+=q.p;s.aquaEvents.harvestC+=q.c}else return false;return true}
return {create,tick,totals,metrics,edit,names};})();if(typeof module!=='undefined')module.exports=Aquatic;
